# Prioritization Methods (JSON)
{
  "methods": {
    "moscow": {
      "name": "MoSCoW",
      "must_have": ["Authentication", "Payment processing"],
      "should_have": ["Analytics dashboard", "Export feature"],
      "could_have": ["Theme customization", "Mobile app"],
      "won_t_have": ["VR integration", "AI chatbot v1"],
      "usage": "Quick categorization, stakeholder alignment"
    },

    "rice": {
      "name": "RICE Scoring",
      "formula": "(Reach * Impact * Confidence) / Effort",
      "example_item": {
        "feature": "Authentication system",
        "reach": "1000 users (per month)",
        "impact": "3 (significant impact)",
        "confidence": "0.8 (80% sure)",
        "effort": "8 weeks",
        "score": "(1000 * 3 * 0.8) / 8 = 300"
      },
      "comparison_item": {
        "feature": "Theme customization",
        "reach": "100 users",
        "impact": "1 (minor impact)",
        "confidence": "0.9 (90% sure)",
        "effort": "4 weeks",
        "score": "(100 * 1 * 0.9) / 4 = 22.5"
      }
    },

    "simple_scoring": {
      "name": "Weighted Scoring",
      "criteria": {
        "business_value": {"weight": 40},
        "urgency": {"weight": 30},
        "technical_risk": {"weight": 20},
        "user_requests": {"weight": 10}
      },
      "scoring_scale": "1-10 per criterion",
      "result": "Weighted total score for ranking"
    }
  }
}
